(()=>{const t=document.querySelector("#blog-search");if(!t)return;const s=document.querySelector("#archive-default"),e=document.querySelector("#search-results"),n=document.querySelector("#search-status");let o,i=0;const a=()=>o||(o=fetch(t.dataset.index).then(e=>{if(!e.ok)throw new Error("Search unavailable");return e.json()}).catch(e=>{throw o=null,e}));t.addEventListener("input",async()=>{const o=++i,r=t.value.trim().toLocaleLowerCase();if(!r){s.hidden=!1,e.hidden=!0,n.textContent="";return}n.textContent="Searching the archive…";try{const c=await a();if(o!==i)return;const l=r.split(/\s+/),t=c.filter(e=>l.every(t=>[e.title,e.text,...e.tags].join(" ").toLocaleLowerCase().includes(t)));e.replaceChildren();for(const n of t){const s=document.createElement("article");s.className="writing-card";const o=document.createElement("p");o.className="post-meta",o.textContent=n.date;const a=document.createElement("h3"),i=document.createElement("a");i.href=n.url,i.textContent=n.title,a.append(i);const r=document.createElement("p");r.textContent=n.summary,s.append(o,a,r),e.append(s)}s.hidden=!0,e.hidden=!1,n.textContent=t.length?`${t.length} ${t.length===1?"article":"articles"} found.`:"No articles found. Try another word or browse the topics."}catch{if(o!==i)return;n.textContent="Search is unavailable right now. You can still browse the archive below.",s.hidden=!1,e.hidden=!0}})})()